const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const cli = path.resolve(__dirname, '../cli.cjs');

function run(cwd, args) {
  const result = spawnSync(process.execPath, [cli, ...args], { cwd, encoding: 'utf8' });
  assert.ifError(result.error);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, '');
  return result.stdout;
}

test('新目录 list 成功且无输出', (t) => {
  const cwd = fs.mkdtempSync(path.resolve(__dirname, '../.name-list-test-'));
  t.after(() => fs.rmSync(cwd, { recursive: true, force: true }));
  assert.equal(run(cwd, ['list']), '');
});

test('独立进程添加名字后按顺序持久化并列出', (t) => {
  const cwd = fs.mkdtempSync(path.resolve(__dirname, '../.name-list-test-'));
  t.after(() => fs.rmSync(cwd, { recursive: true, force: true }));
  const names = ['张 三', '李,小"明'];
  for (const name of names) run(cwd, ['add', name]);
  assert.equal(run(cwd, ['list']), names.join('\n') + '\n');
  assert.deepEqual(JSON.parse(fs.readFileSync(path.join(cwd, 'names.json'), 'utf8')), names);
});
# name-list

name-list 是本地名字列表命令行工具，支持添加和查看名字。

数据只在本地保存，重启后仍可读取。

运行需要 Node 24。

无需安装第三方依赖。在项目目录运行：

```sh
node cli.cjs add "张 三"
node cli.cjs add '李,小"明'
node cli.cjs list
```

名字按添加顺序逐行输出，重复名字会保留；空列表没有输出。
`add` 接受一个非空名字参数，包含空格的名字需要引号包裹。
缺失名字或未知命令会向 stderr 提示错误，并以非零状态退出。

数据以 JSON 字符串数组保存在**运行命令时的当前工作目录**下的 `names.json`，
不同工作目录使用各自的数据文件。文件不存在时视为空列表；存储损坏时会报错，不覆盖原文件。
从其他目录运行时，请使用 `cli.cjs` 的绝对路径。

运行两个集成测试：

```sh
npm test
